import{_ as e,o as a,c as r,ag as i}from"./chunks/framework.4s5LDCII.js";const p=JSON.parse('{"title":"中国居民膳食指南（2022）","description":"中国营养学会《中国居民膳食指南（2022）》八条准则导读：一般人群的日常膳食总纲。","frontmatter":{"title":"中国居民膳食指南（2022）","issuer":"中国营养学会","source_tier":"二级来源","version":2022,"published":"2022-04","document_no":null,"source_url":"http://dg.cnsoc.org/","status":"现行","tags":["膳食指南","营养","健康饮食"],"reviewed":false,"description":"中国营养学会《中国居民膳食指南（2022）》八条准则导读：一般人群的日常膳食总纲。"},"headers":[],"relativePath":"guides/dietary-guidelines-2022.md","filePath":"guides/dietary-guidelines-2022.md"}'),o={name:"guides/dietary-guidelines-2022.md"};function l(d,t,s,n,c,u){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="中国居民膳食指南-2022" tabindex="-1">中国居民膳食指南（2022） <a class="header-anchor" href="#中国居民膳食指南-2022" aria-label="Permalink to &quot;中国居民膳食指南（2022）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：中国营养学会发布（<a href="http://dg.cnsoc.org/" target="_blank" rel="noreferrer">膳食指南官网</a>）· <strong>二级来源</strong>（行业专业机构，非政府部门）</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>所有一般人群——它是日常&quot;怎么吃&quot;的总纲；具体到某一种疾病（如高血压、糖尿病），请再配合卫健委对应的食养指南阅读。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><p>指南对一般人群提出<strong>八条准则</strong>：</p><ol><li>食物多样，合理搭配</li><li>吃动平衡，健康体重</li><li>多吃蔬果、奶类、全谷、大豆</li><li>适量吃鱼、禽、蛋、瘦肉</li><li>少盐少油，控糖限酒</li><li>规律进餐，足量饮水</li><li>会烹会选，会看标签</li><li>公筷分餐，杜绝浪费</li></ol><p>配套的核心推荐量（如每日食盐不超 5 克、烹调油 25–30 克、添加糖控制到 50 克以下最好 25 克以下、每天至少 12 种食物每周 25 种等）详见原文。</p><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>把八准则当&quot;总纲&quot;：日常采购、做饭、看配料表时对照执行；需要针对具体慢性病调整时，再查对应疾病的食养指南词条。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>中国营养学会（二级来源）</td></tr><tr><td>版本</td><td>2022 版（现行）</td></tr><tr><td>发布时间</td><td>2022 年 4 月（具体日期待核对原文）</td></tr></tbody></table>',13)])])}const _=e(o,[["render",l]]);export{p as __pageData,_ as default};
